    24|
    25|export const IVX_SENIOR_DEV_WORKER_ID = 'IVX-SENIOR-DEV-01';
    26|export const WORKER_HEARTBEAT_SECONDS = 30;
    27|export const TASK_POLL_INTERVAL_MS = 5_000;
    28|export const TASK_CLAIM_TIMEOUT_MS = 3 * 60 * 1000; // 3 minutes
    29|
    30|export type IVXSeniorDevWorkerPhase =
    31|  | 'CLAIMED'
    32|  | 'PLANNING'
