    44|
    45|export interface IVXSeniorDevWorkerRuntime {
    46|  workerId: string;
    47|  startedAt: string;
    48|  lastTickAt: string;
    49|  currentTaskId: string | null;
    50|  currentPhase: IVXSeniorDevWorkerPhase | null;
