    75|export async function startSeniorDevWorker(): Promise<void> {
    76|  console.log('[IVX-SENIOR-DEV-01] Worker starting', { workerId: IVX_SENIOR_DEV_WORKER_ID, at: state.startedAt });
    77|  while (!stopRequested) {
    78|    state.lastTickAt = new Date().toISOString();
    79|    try {
    80|      await tick();
    81|    } catch (error) {
    82|      state.errorCount += 1;
    83|      console.log('[IVX-SENIOR-DEV-01] Tick error:', error instanceof Error ? error.message : 'unknown');
    84|    }
    85|    await sleep(TASK_POLL_INTERVAL_MS);
