    91|async function tick(): Promise<void> {
    92|  const tasks = await listTasks(50);
    93|  // Find a senior_dev task that is QUEUED or RETRYING and not currently claimed.
    94|  const candidates = tasks.filter((t) => {
    95|    if (t.task_type !== 'senior_dev') return false;
    96|    if (t.status !== 'QUEUED' && t.status !== 'RETRYING') return false;
    97|    if (t.assigned_worker_id && t.assigned_worker_id !== IVX_SENIOR_DEV_WORKER_ID) return false;
    98|    return true;
    99|  });
   100|
   101|  if (candidates.length === 0) return;
   102|
   103|  // Pick the oldest task.
   104|  const task = candidates.sort((a, b) => new Date(a.created_at).getTime() - new Date(b.created_at).getTime())[0];
   105|  if (!task) return;
   106|
   107|  const claimed = await claimTask(task.id);
   108|  if (!claimed) return;
   109|
   110|  state.currentTaskId = task.id;
   111|  state.runCount += 1;
   112|
   113|  try {
