   115|  } catch (error) {
   116|    state.errorCount += 1;
   117|    console.log('[IVX-SENIOR-DEV-01] executeSeniorDevTask error:', error instanceof Error ? error.message : 'unknown');
   118|    await failTask(task.id, error instanceof Error ? error.message : 'unknown');
   119|  } finally {
   120|    state.currentTaskId = null;
   121|    state.currentPhase = null;
   122|  }
