   125|async function claimTask(taskId: string): Promise<IVXOwnerAITaskRow | null> {
   126|  const now = new Date().toISOString();
   127|  const patched = await patchTask(taskId, {
   128|    status: 'RUNNING',
   129|    checkpoint: `CLAIMED by ${IVX_SENIOR_DEV_WORKER_ID}`,
   130|    assigned_worker_id: IVX_SENIOR_DEV_WORKER_ID,
   131|    heartbeat_at: now,
   132|    checkpoint_history: appendCheckpoint(null, `CLAIMED by ${IVX_SENIOR_DEV_WORKER_ID} at ${now}`),
   133|  }, `&status=in.(QUEUED,RETRYING)&assigned_worker_id=is.null`);
   134|  return patched;
