   137|async function executeSeniorDevTask(task: IVXOwnerAITaskRow): Promise<void> {
   138|  const run = await writeProofLedger({
   139|    taskId: task.id,
   140|    workerId: IVX_SENIOR_DEV_WORKER_ID,
