   154|
   155|  // Phase 2: INSPECTING
   156|  await setPhase(task.id, 'INSPECTING', runId);
   157|  const inspectedFiles = ['backend/api/ivx-owner-ai.ts', 'backend/services/ivx-owner-ai-task-queue.ts'];
   158|  await logCheckpoint(task.id, runId, 'INSPECTING', { files: inspectedFiles });
   159|  await updateProofLedger(runId, { filesInspected: inspectedFiles });
   160|
   161|  // Phase 3: IMPLEMENTING (placeholder — real worker will edit files here)
   162|  await setPhase(task.id, 'IMPLEMENTING', runId);
   163|  const changedFiles: string[] = [];
   164|  await logCheckpoint(task.id, runId, 'IMPLEMENTING', { filesChanged: changedFiles });
   165|  await updateProofLedger(runId, { filesChanged: changedFiles });
   166|
   167|  // Phase 4: TESTING
   168|  await setPhase(task.id, 'TESTING', runId);
   169|  const testResults = { typecheck: 'pending', lint: 'pending', tests: 'pending' };
   170|  await logCheckpoint(task.id, runId, 'TESTING', testResults);
   171|  await updateProofLedger(runId, { testResults });
   172|
   173|  // Phase 5: WAITING_APPROVAL (if production mutation required)
   174|  const workerData = (task.worker_data ?? {}) as Record<string, unknown>;
   175|  const requestsDeploy = workerData.requestsDeploy === true;
   176|  if (requestsDeploy) {
   177|    await setPhase(task.id, 'WAITING_APPROVAL', runId);
   178|    await logCheckpoint(task.id, runId, 'WAITING_APPROVAL', { action: 'GITHUB_WRITE+RENDER_DEPLOY' });
   179|    await patchTask(task.id, {
   180|      status: 'WAITING_APPROVAL',
