   186|    if (!approved) {
   187|      await failTask(task.id, 'Approval timeout or missing.');
   188|      await updateProofLedger(runId, { status: 'failed', errorMessage: 'Approval timeout or missing.' });
   189|      return;
   190|    }
   191|  }
   192|
   193|  // Phase 6: COMMITTING
   194|  await setPhase(task.id, 'COMMITTING', runId);
   195|  const commitSha = `placeholder-${randomUUID().slice(0, 12)}`;
   196|  await logCheckpoint(task.id, runId, 'COMMITTING', { commitSha });
   197|  await updateProofLedger(runId, { commitSha });
   198|  await patchTask(task.id, { commit_sha: commitSha });
   199|
   200|  // Phase 7: DEPLOYING
   201|  if (requestsDeploy) {
   202|    await setPhase(task.id, 'DEPLOYING', runId);
   203|    const deployId = `placeholder-${randomUUID().slice(0, 12)}`;
   204|    await logCheckpoint(task.id, runId, 'DEPLOYING', { deployId });
   205|    await updateProofLedger(runId, { renderDeployId: deployId });
   206|    await patchTask(task.id, { render_deploy_id: deployId });
